using Microsoft.Extensions.Options;
using UCE.Application.Documents.Abstractions;
using UCE.Application.Documents.Models;
using UCE.Domain.Enums;
namespace UCE.Infrastructure.Documents.Structure;
public sealed class DocumentStructureBuilder(IOptions<StructureBuilderOptions> options,IHeadingDetector headingDetector,IContentBlockClassifier classifier) : IDocumentStructureBuilder
{
 private readonly StructureBuilderOptions _options=options.Value;
 public DocumentStructure Build(ParsedDocument document) { ArgumentNullException.ThrowIfNull(document); var result=new DocumentStructure{FullText=document.FullText}; var paragraphs=document.ParsedParagraphs.OrderBy(x=>x.Order).ToList(); if(paragraphs.Count==0 && document.Pages.Count>0) paragraphs=FromPages(document.Pages); if(paragraphs.Count==0)return result; var stack=new Stack<DocumentStructureSection>(); DocumentStructureSection? current=null; if(_options.CreateRootSection){var root=new DocumentStructureSection{Title=_options.RootSectionTitle,Level=0,Order=0,StartPosition=0};result.Sections.Add(root);stack.Push(root);current=root;} int order=1; foreach(var p in paragraphs){var h=headingDetector.Detect(p); if(h.IsHeading){while(stack.Count>0&&stack.Peek().Level>=Math.Clamp(h.Level??_options.DefaultHeadingLevel,1,_options.MaximumHeadingLevel)){var done=stack.Pop();done.EndPosition=Math.Max(done.StartPosition,p.StartPosition);} var level=Math.Clamp(h.Level??_options.DefaultHeadingLevel,1,_options.MaximumHeadingLevel);var section=new DocumentStructureSection{Title=p.Text.Trim(),Level=level,Order=order++,StartPosition=p.StartPosition};if(stack.Count>0){var parent=stack.Peek();section.ParentId=parent.Id;parent.Children.Add(section);}else result.Sections.Add(section);stack.Push(section);current=section;result.Paragraphs.Add(new DocumentParagraph{Order=p.Order,Text=p.Text,StartPosition=p.StartPosition,EndPosition=p.EndPosition,PageNumber=p.PageNumber,IsHeading=true,HeadingLevel=level,StyleName=p.StyleName,Type=ContentBlockType.Heading,SectionId=section.Id});continue;} var c=classifier.Classify(p);var dp=new DocumentParagraph{Order=p.Order,Text=p.Text,StartPosition=p.StartPosition,EndPosition=p.EndPosition,PageNumber=p.PageNumber,StyleName=p.StyleName,Type=c.Type,Marker=c.Marker,SectionId=current?.Id};current?.Paragraphs.Add(dp);result.Paragraphs.Add(dp);} while(stack.Count>0){var s=stack.Pop();s.EndPosition=Math.Max(s.StartPosition,document.FullText.Length);} return result; }
 private static List<ParsedParagraph> FromPages(IReadOnlyCollection<ParsedPage> pages){var output=new List<ParsedParagraph>();int global=0,order=0;foreach(var page in pages.OrderBy(p=>p.PageNumber)){var text=page.Text??"";int offset=0;foreach(var line in text.Split('\n')){var clean=line.Trim();var idx=text.IndexOf(line,offset,StringComparison.Ordinal);if(clean.Length>0&&idx>=0)output.Add(new(){Text=clean,Order=order++,StartPosition=global+idx,EndPosition=global+idx+line.Length,PageNumber=page.PageNumber});offset=Math.Max(offset,idx+line.Length+1);}global+=text.Length+2;}return output;}
}